"""Authored, behavioral Delve perks; values use seconds until code generation."""

import re


def extended_description(description):
    return re.sub(r'(for (?:up to )?|within |lasting )(\d+(?:\.\d+)?)s',
                  lambda match: match[1] + format(float(match[2]) * 1.25, 'g') + 's', description)


def perk(name, kind, reward, value, duration, cooldown, description, ability=-1):
    return dict(name=name, kind=kind, reward=reward, value=value, duration=duration * 1.25,
                cooldown=cooldown, filter=ability, description=extended_description(description))


